export const playbook = "<!doctype html><html lang=\"fr\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Solaya — Tunnel d’acquisition propriétaires</title><style>*{box-sizing:border-box}body{margin:0;background:#f7f3ea;color:#294338;font:16px/1.7 Arial,sans-serif}header{padding:65px 8%;background:#29483c;color:#fff8eb}header p{color:#e4cda4;max-width:760px}.brand{letter-spacing:.22em;font-size:12px}h1,h2,h3{font-family:Georgia,serif;font-weight:400;line-height:1.2}h1{font-size:clamp(36px,6vw,70px);max-width:920px;margin:20px 0}h2{font-size:34px;margin:0 0 30px}h3{font-size:24px;margin-top:30px}.layout{display:grid;grid-template-columns:270px 1fr;max-width:1500px;margin:auto}nav{position:sticky;top:0;height:100vh;overflow:auto;padding:30px 22px;border-right:1px solid #ded5c4}nav a{display:block;font-size:13px;color:#294338;margin:0 0 15px;text-decoration:none}main{min-width:0;padding:35px 6%}section{padding:35px 0 60px;border-bottom:1px solid #d6cdbd;scroll-margin-top:20px}a{color:#71551f;text-underline-offset:3px}header a{color:#efdbb7}.lead{font-size:21px}.callout,.quote{background:#e9dfcb;border-left:4px solid #aa834c;padding:22px;margin:24px 0}.quote{font:26px/1.4 Georgia,serif}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px;margin:25px 0}th{background:#29483c;color:white;text-align:left;padding:14px}td{padding:15px 13px;border-bottom:1px solid #d6cdbd;vertical-align:top}tr:nth-child(even){background:#eee8dc}.template{position:relative;background:#fffdf7;border:1px solid #dcd0bb;padding:22px;margin:22px 0}.template h3{margin-top:0;padding-right:75px;font-size:22px}pre{white-space:pre-wrap;font:14px/1.8 Arial,sans-serif;margin-bottom:0;overflow-wrap:anywhere}.copy{position:absolute;right:15px;top:15px}button{cursor:pointer;border:1px solid #b6a88d;background:#f2eadb;color:#294338;border-radius:4px;padding:9px 14px}.checklist label{display:flex;gap:14px;padding:15px;border-bottom:1px solid #ddd0bb}.checklist input{width:20px;height:20px;flex:none;margin-top:3px}.checklist label:has(input:checked){color:#6f796d;text-decoration:line-through}footer{padding:30px 8%;font-size:12px}code{overflow-wrap:anywhere}@media(max-width:900px){.layout{display:block}nav{position:static;height:auto;display:flex;flex-wrap:wrap;gap:12px;padding:20px}nav a{margin:0;font-size:11px}main{padding:20px 5%}h2{font-size:29px}header{padding:40px 6%}}@media print{nav,button{display:none}.layout{display:block}header{background:white;color:#294338;padding:25px}header p{color:#294338}main{padding:0}section{break-before:page;padding:15px}.template,table tr{break-inside:avoid}a{color:inherit}body{font-size:12px}pre,table{font-size:11px}h1{font-size:35px}h2{font-size:26px}}</style><header><span class=\"brand\">SOLAYA COLLECTION / DOSSIER OPÉRATIONNEL</span><h1>Des premiers échanges<br>aux premiers logements.</h1><p>Le tunnel d’acquisition propriétaires. Pages, campagnes, qualification, vente et intégration — version du 14 septembre 2026.</p><button onclick=\"window.print()\">Imprimer / enregistrer en PDF</button></header><div class=\"layout\"><nav><a href=\"#s0\">01 · Ce qui est prêt, ce qui reste à raccorder</a><a href=\"#s1\">02 · Offre d’entrée et profils prioritaires</a><a href=\"#s2\">03 · Le parcours, avec critères de passage</a><a href=\"#s3\">04 · Canaux et plan de lancement sur 30 jours</a><a href=\"#s4\">05 · Campagnes prêtes à configurer</a><a href=\"#s5\">06 · Messages réseau et partenaires</a><a href=\"#s6\">07 · Séquences de suivi prêtes à adapter</a><a href=\"#s7\">08 · Sept publications prêtes à personnaliser</a><a href=\"#s8\">09 · Entretien de qualification de 20 minutes</a><a href=\"#s9\">10 · Trame d’étude du logement</a><a href=\"#s10\">11 · Proposition commerciale et signature</a><a href=\"#s11\">12 · Intégration et première mise en service</a><a href=\"#s12\">13 · Mesure, coûts et décisions</a><a href=\"#s13\">14 · Automatisations : périmètre réel et raccordements</a><a href=\"#s14\">15 · Dernières décisions avant diffusion</a></nav><main><section id=\"s0\"><h2>01 · Ce qui est prêt, ce qui reste à raccorder</h2><p class=\"lead\">De la découverte de Solaya au premier logement actif : un parcours préparé pour une acquisition progressive à Toulouse et ses environs.</p><div class=\"callout\">Le site reste privé. Il permet de vérifier le parcours, mais ne peut pas encore recevoir librement des propriétaires. L’ouverture au public, les mentions définitives, les prestataires et les outils de communication sont les derniers éléments à finaliser.</div><div class=\"table-wrap\"><table><thead><tr><th>Élément</th><th>État</th><th>Utilisation</th></tr></thead><tbody><tr><td>Pages propriétaires</td><td>Construit</td><td>Deux entrées : location existante / nouveau projet, puis étude du logement.</td></tr><tr><td>Qualification</td><td>Construit</td><td>Formulaire en trois étapes, enregistrement en base, référence, consentement distinct.</td></tr><tr><td>Suivi commercial</td><td>Construit</td><td>11 étapes, responsable, échéance, notes, historique, export, arrêt de contact et effacement.</td></tr><tr><td>Messages</td><td>Préparés</td><td>Modèles personnalisables ci-dessous et brouillons dans le CRM. Aucun envoi automatique.</td></tr><tr><td>Rendez-vous</td><td>Manuel</td><td>Le propriétaire propose ses créneaux ; confirmation après vérification de vos agendas.</td></tr><tr><td>Signature / paiement</td><td>À raccorder</td><td>Le CRM suit le contrat reçu ; il ne signe pas et n’encaisse pas.</td></tr><tr><td>Diffusion publicitaire</td><td>Préparée, inactive</td><td>Textes, destinations et tests ci-dessous. Aucun compte raccordé, aucune dépense engagée.</td></tr><tr><td>Étude économique</td><td>Trame prête</td><td>À remplir avec données du bien ; aucun revenu de marché inventé.</td></tr><tr><td>Données légales</td><td>À compléter</td><td>Raison sociale, adresse, statut, prix HT/TTC, contrat, responsabilité, traitement des données.</td></tr></tbody></table></div><p><a href=\"https://solaya-collection-kevin.kevindolie1.chatgpt.site/etude\">Tester le formulaire</a> · <a href=\"https://solaya-collection-kevin.kevindolie1.chatgpt.site/pilotage\">Ouvrir le suivi privé</a> · <a href=\"https://solaya-collection-kevin.kevindolie1.chatgpt.site/guide-proprietaire\">Lire le guide propriétaire</a></p><p>Compte de pilotage : kevindolie1@gmail.com. Désigner Adrien comme responsable d’une action ne lui ouvre pas l’accès et ne lui envoie pas de notification.</p></section><section id=\"s1\"><h2>02 · Offre d’entrée et profils prioritaires</h2><h3>Promesse centrale</h3><p class=\"quote\">Votre logement mérite une gestion attentive. Commençons par une étude claire de votre projet, de vos contraintes et de ses revenus nets possibles.</p><p>L’appel à l’action unique est <strong>« Faire étudier mon logement »</strong>. Le premier échange est sans engagement. L’étude complète et la visite sont proposées après qualification ; ne promettre ni revenu, ni hausse de rentabilité, ni disponibilité opérationnelle non vérifiée.</p><div class=\"table-wrap\"><table><thead><tr><th>Profil</th><th>Motivation</th><th>Angle de la page</th><th>Qualification</th></tr></thead><tbody><tr><td>Loue déjà</td><td>Messages, ménage et coordination prennent trop de temps.</td><td>Moins de coordination, plus de recul.</td><td>12 mois de recettes et charges, taux d’occupation constaté, contrats existants, date de transfert.</td></tr><tr><td>Prépare un projet</td><td>Veut décider avant d’investir ou de changer de location.</td><td>Comparer les scénarios et les contraintes.</td><td>Adresse, statut, calendrier, budget d’équipement, décideurs, autorisations à vérifier.</td></tr><tr><td>Hors zone / bien peu disponible</td><td>Besoin réel mais faisabilité incertaine.</td><td>Écoute, réponse honnête, orientation éventuelle.</td><td>Ne pas rejeter automatiquement : vérifier couverture, capacité et économie du dossier.</td></tr></tbody></table></div><h3>Priorité interne</h3><p>Le score du CRM aide à trier, jamais à accepter automatiquement : département 31 = 30 points ; disponibilité supérieure à 6 mois = 25, de 3 à 6 mois = 15 ; démarrage immédiat = 20 ou sous 3 mois = 10 ; au moins 2 chambres = 15 ; location déjà active = 10. Le nombre de chambres est un signal de positionnement, pas un critère exclusif. La couverture terrain reste à confirmer pour chaque commune.</p><h3>Prix : décision interne à prendre</h3><p>Vos échanges mentionnent 490 € de démarrage et 20 % de commission, avec une variante à 25 %. Ces montants ne sont pas affichés comme offre ferme sur le site. Adrien doit trancher le prix, son caractère HT/TTC, la base de commission, les prestations incluses, le ménage et les frais de plateformes, le matériel, les interventions et la résiliation.</p></section><section id=\"s2\"><h2>03 · Le parcours, avec critères de passage</h2><div class=\"table-wrap\"><table><thead><tr><th>Étape</th><th>Action / responsable proposé</th><th>Condition de sortie</th></tr></thead><tbody><tr><td>Nouvelle demande</td><td>Kevin : examiner le formulaire, vérifier les doublons, préparer la réponse avant la prochaine journée ouvrée.</td><td>Prochaine action datée ; réponse réellement effectuée.</td></tr><tr><td>Contact établi</td><td>Kevin : convenir d’un échange de 20 minutes.</td><td>Deux parties d’accord sur date et canal.</td></tr><tr><td>RDV convenu</td><td>Kevin : préparer données connues et questions ouvertes.</td><td>Échange réalisé ou nouveau créneau convenu.</td></tr><tr><td>Bien qualifié</td><td>Kevin + Adrien : vérifier décideur, zone, capacité, contraintes et adéquation.</td><td>Case de qualification humaine validée et compte rendu.</td></tr><tr><td>Étude en cours</td><td>Adrien : hypothèses et frais ; Kevin : annonce, expérience, besoins digitaux.</td><td>Étude traçable, trois scénarios et actions préalables.</td></tr><tr><td>Proposition envoyée</td><td>Adrien : offre validée ; Kevin : présentation au propriétaire.</td><td>Proposition réellement jointe/envoyée, date et prochaine relance consignées.</td></tr><tr><td>Contrat signé</td><td>Adrien : contrat reçu, cohérent avec l’offre et archivé.</td><td>Case contrat reçu ; aucun simple accord oral.</td></tr><tr><td>Intégration</td><td>Kevin + Adrien : liste d’installation, prestataires, accès et contenus.</td><td>Tous les contrôles de mise en service sont terminés.</td></tr><tr><td>Bien actif</td><td>Adrien valide le terrain, Kevin valide les parcours numériques.</td><td>Démarches, ménage, accès, paiement et photos validés en plus du contrat.</td></tr><tr><td>En pause</td><td>Kevin : motif et éventuelle date de reprise convenue.</td><td>Reprise demandée ou convenue, pas de relance indéfinie.</td></tr><tr><td>Clôturé</td><td>Kevin : motif de perte, retrait de consentement si demandé.</td><td>Aucune prochaine action commerciale. Revue de conservation.</td></tr></tbody></table></div><p>Le CRM contrôle la qualification avant l’étude/proposition, le contrat avant la signature/intégration et les cinq validations avant « actif ». Une case validée signifie qu’un humain a contrôlé et documenté le point ; elle ne remplace aucun document. Un dossier « arrêt de contact » doit rester en pause ou clôturé.</p></section><section id=\"s3\"><h2>04 · Canaux et plan de lancement sur 30 jours</h2><div class=\"table-wrap\"><table><thead><tr><th>Période</th><th>Travail concret</th><th>Responsable</th><th>Indicateur</th></tr></thead><tbody><tr><td>J1–J3</td><td>Finaliser offre et périmètre ; tester formulaire et fiche ; compléter mentions ; choisir créneaux de traitement quotidiens.</td><td>Kevin + Adrien</td><td>Test de bout en bout réussi, capacité hebdomadaire connue.</td></tr><tr><td>J4–J7</td><td>Reprendre les contacts qui ont déjà demandé un échange ; demander aux relations de transmettre le lien sans fournir le fichier de leurs contacts.</td><td>Kevin</td><td>Demandes volontaires et rendez-vous réellement convenus.</td></tr><tr><td>J8–J14</td><td>Présenter l’offre aux partenaires locaux pertinents ; publier les contenus 1 à 3 ; réaliser les premières études.</td><td>Adrien / Kevin</td><td>Partenaires actifs, demandes qualifiées, temps par étude.</td></tr><tr><td>J15–J21</td><td>Présenter les propositions, collecter les objections, améliorer les réponses ; lancer un petit test payant seulement si le parcours est public et opérationnel.</td><td>Adrien / Kevin</td><td>Propositions, signatures, coût et qualité par source.</td></tr><tr><td>J22–J30</td><td>Intégrer les premiers biens compatibles avec la capacité terrain ; bilan des pertes et du coût ; décider du canal à amplifier.</td><td>Les deux</td><td>Biens signés puis activés, marge estimée, charge réelle.</td></tr></tbody></table></div><h3>Ordre des canaux</h3><ol><li>Demandes déjà exprimées et réseau personnel ayant accepté un échange.</li><li>Recommandation volontaire : l’intermédiaire transmet le lien au propriétaire.</li><li>Partenaires professionnels locaux : agences, artisans, photographes et réseaux d’affaires, selon pertinence réelle.</li><li>Contenus organiques locaux renvoyant vers une page propriétaire.</li><li>Test de recherche payante, après validation des conversions et de la capacité.</li></ol><p>Ne pas utiliser de fichiers clients Crédit Agricole ni extraire les coordonnées de particuliers depuis leurs annonces pour des campagnes. Les contacts existants cités dans vos réunions ne sont pas importés : leurs coordonnées et leur accord n’ont pas été fournis.</p><h3>Cadence de traitement proposée</h3><p>Deux créneaux de 20 minutes par jour ouvré pour consulter le CRM ; un point Kevin/Adrien de 30 minutes chaque semaine. Objectif interne : traiter une nouvelle demande dans la prochaine journée ouvrée, sans afficher de délai garanti au propriétaire. Réduire la diffusion si les demandes attendent plus de deux jours ouvrés ou si la capacité ménage n’est pas confirmée.</p></section><section id=\"s4\"><h2>05 · Campagnes prêtes à configurer</h2><p>Les liens ci-dessous sont construits pour le site actuel, encore privé. Après ouverture ou raccordement du domaine, remplacer la racine partout. Le formulaire conserve <code>utm_source</code> et <code>utm_campaign</code>. Les clics et impressions ne sont pas mesurés dans le CRM.</p><div class=\"table-wrap\"><table><thead><tr><th>Canal</th><th>Destination</th><th>Convention</th></tr></thead><tbody><tr><td>Réseau</td><td><a href=\"https://solaya-collection-kevin.kevindolie1.chatgpt.site/etude?utm_source=reseau&utm_campaign=proprietaires_pilote\">/etude</a></td><td>reseau / proprietaires_pilote</td></tr><tr><td>Partenaires</td><td><a href=\"https://solaya-collection-kevin.kevindolie1.chatgpt.site/etude?utm_source=partenaires&utm_campaign=proprietaires_pilote\">/etude</a></td><td>partenaires / proprietaires_pilote</td></tr><tr><td>Instagram</td><td><a href=\"https://solaya-collection-kevin.kevindolie1.chatgpt.site/proprietaires/deja-en-location?utm_source=instagram&utm_campaign=delegation_toulouse\">/proprietaires/deja-en-location</a></td><td>instagram / delegation_toulouse</td></tr><tr><td>LinkedIn</td><td><a href=\"https://solaya-collection-kevin.kevindolie1.chatgpt.site/proprietaires/nouveau-projet?utm_source=linkedin&utm_campaign=projet_toulouse\">/proprietaires/nouveau-projet</a></td><td>linkedin / projet_toulouse</td></tr><tr><td>Recherche payante</td><td><a href=\"https://solaya-collection-kevin.kevindolie1.chatgpt.site/proprietaires/deja-en-location?utm_source=google&utm_campaign=gestion_toulouse\">/proprietaires/deja-en-location</a></td><td>google / gestion_toulouse</td></tr></tbody></table></div><h3>Structure du test de recherche</h3><p>Deux groupes séparés : <strong>gestion existante</strong> et <strong>nouveau projet</strong>. Cibler le périmètre réellement couvert, pas toute la France. Démarrer avec des intentions précises et relire les requêtes avant d’élargir. Confirmer dans le compte publicitaire les options disponibles au moment de configurer.</p><article class=\"template\"><h3>Groupe A — propriétaires qui louent déjà</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Mots-clés de départ à tester :\nconciergerie Toulouse\ngestion location courte durée Toulouse\nconciergerie appartement Toulouse\n\nTitres :\nConciergerie à Toulouse\nConfiez votre logement\nSolaya Collection\nMoins de gestion au quotidien\nÉtudions votre logement\n\nDescriptions :\nVotre logement mérite une gestion attentive. Présentez votre projet à Solaya.\nMénage, accueil, annonces : étudions les services adaptés à votre logement.\n\nDestination : /proprietaires/deja-en-location\nCTA : Faire étudier mon logement</pre></article><article class=\"template\"><h3>Groupe B — nouveau projet</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Mots-clés de départ à tester :\nmettre appartement location courte durée Toulouse\nconciergerie propriétaire Toulouse\n\nTitres :\nUn projet locatif à Toulouse\nPréparez votre mise en location\nParlons de votre logement\nDes scénarios expliqués\n\nDescriptions :\nAvant de vous lancer, comparez contraintes, frais et scénarios de location.\nPrésentez votre bien. Un premier échange pour préciser votre projet, sans engagement.\n\nDestination : /proprietaires/nouveau-projet\nCTA : Présenter mon projet</pre></article><article class=\"template\"><h3>Exclusions initiales à examiner</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">emploi\nrecrutement\nstage\nsalaire\nformation\nconcierge gardien\nlocation vacances pas cher\nréserver appartement\nweek-end hôtel\n\nÀ adapter aux requêtes réellement observées. Ne pas exclure « prix », « avis » ou « propriétaire », qui peuvent traduire une intention utile.</pre></article><h3>Budget et règle d’arrêt</h3><p>Hypothèse de test à approuver, pas une recommandation issue de prix de marché : enveloppe totale de 200 € sur 14 jours maximum, uniquement si ce montant est acceptable et la capacité disponible. Ne pas activer plusieurs campagnes qui consommeraient chacune cette enveloppe. Arrêt immédiat si le formulaire échoue ou la source ne remonte pas ; revue à 100 € dépensés, sans extrapoler une rentabilité sur un ou deux contacts. Sans prospect qualifié au plafond, arrêter et revoir ciblage/message/offre.</p><p>Aucun pixel publicitaire ni synchronisation de conversion n’est installé. Le suivi minimal repose sur les demandes attribuées et les dépenses reportées depuis le compte ; le taux de conversion visite→demande restera inconnu tant qu’une mesure de visites appropriée n’est pas raccordée.</p></section><section id=\"s5\"><h2>06 · Messages réseau et partenaires</h2><article class=\"template\"><h3>Recommandation — transmettre le lien, sans partager de coordonnées</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Bonjour [Prénom],\n\nAvec Adrien, nous préparons Solaya Collection, un accompagnement pour les propriétaires qui souhaitent déléguer la gestion de leur location à Toulouse et dans les environs que nous pouvons couvrir.\n\nSi tu connais quelqu’un qui se pose la question, tu peux lui transmettre ce lien : [lien réseau]. Il pourra nous présenter son logement directement, sans engagement.\n\nL’idée est de regarder son projet sérieusement : contraintes, frais, organisation et scénarios de revenus nets. Merci !\nKevin</pre></article><article class=\"template\"><h3>Professionnel local — prise de contact ciblée</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Objet : Un échange local autour des propriétaires à Toulouse\n\nBonjour [Prénom / Nom],\n\nJe vous contacte au sujet de votre activité de [activité pertinente] à [commune]. Avec Adrien, nous préparons Solaya Collection pour accompagner des propriétaires dans la gestion de leur location.\n\nJe souhaiterais comprendre les besoins que vous rencontrez et vous présenter notre fonctionnement en 15 minutes. Si un propriétaire souhaite être accompagné, nous privilégions une mise en relation à son initiative ou avec son accord.\n\nSeriez-vous disponible pour un court échange ?\n\nKevin — Solaya Collection\nkevin.dolie@solayia.fr\nSi ce sujet ne vous concerne pas ou si vous ne souhaitez plus être contacté, dites-le-moi simplement.</pre></article><article class=\"template\"><h3>Après rendez-vous partenaire</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Objet : Suite à notre échange — Solaya Collection\n\nBonjour [Prénom],\n\nMerci pour notre échange. Nous retenons :\n• Votre activité / vos besoins : [résumé fidèle].\n• Les logements que nous pouvons étudier : [périmètre confirmé].\n• La mise en relation : vous transmettez [lien partenaire] au propriétaire intéressé.\n• Notre prochain point : [date convenue].\n\nNous ne présentons aucune rémunération d’apporteur comme acquise : toute éventuelle convention sera définie et validée séparément.\n\nKevin — Solaya Collection</pre></article><p>Le premier message réseau n’est à utiliser que dans une relation et un contexte où cette sollicitation est appropriée. Pour un e-mail commercial à un particulier, obtenir le consentement requis ; une simple présence dans un carnet d’adresses ne suffit pas.</p></section><section id=\"s6\"><h2>07 · Séquences de suivi prêtes à adapter</h2><p>Les jours ci-dessous sont des repères après une demande volontaire, pas une automatisation active. Réponse reçue, rendez-vous pris, refus, plainte, erreur d’adresse ou arrêt de contact : suspendre immédiatement la séquence et traiter la situation. Ne pas inscrire une personne aux contenus commerciaux sur la seule base d’une demande d’étude.</p><div class=\"table-wrap\"><table><thead><tr><th>Moment</th><th>Message</th><th>Condition</th></tr></thead><tbody><tr><td>J0 ouvré</td><td>Accusé et proposition d’échange</td><td>Demande reçue et lue</td></tr><tr><td>J+2 ouvrés</td><td>Relance courte</td><td>Aucune réponse et demande toujours pertinente</td></tr><tr><td>J+7 ouvrés</td><td>Dernier suivi puis pause</td><td>Toujours aucune réponse ; pas de série sans fin</td></tr><tr><td>Après échange</td><td>Récapitulatif et données attendues</td><td>Compte rendu fidèle</td></tr><tr><td>Après étude</td><td>Proposition personnalisée</td><td>Offre validée et document joint</td></tr><tr><td>J+3 après proposition</td><td>Question sur la décision</td><td>Pas de réponse, pas de refus</td></tr><tr><td>J+10 après proposition</td><td>Clôture ou report</td><td>Dernière relance sans réponse</td></tr><tr><td>Après signature</td><td>Démarrage de l’intégration</td><td>Contrat reçu et archivé</td></tr></tbody></table></div><article class=\"template\"><h3>01 — Accusé de réception</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Objet : Votre projet à [Ville] — Solaya\n\nBonjour [Prénom],\n\nMerci pour votre demande au sujet de votre logement à [Ville]. Pour préparer une étude utile, pouvons-nous convenir d’un échange de 20 minutes ? Vous pouvez me proposer deux créneaux.\n\nNous parlerons de votre objectif, de vos périodes disponibles et des contraintes du bien. Si une annonce existe déjà, son lien nous aidera.\n\nKevin — Solaya Collection</pre></article><article class=\"template\"><h3>02 — Relance de la demande</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Objet : Votre logement à [Ville]\n\nBonjour [Prénom],\n\nSouhaitez-vous toujours que nous regardions votre projet ensemble ? Vous pouvez me proposer un créneau ou m’indiquer une période plus adaptée. Si votre projet a changé, dites-le-moi simplement.\n\nKevin — Solaya Collection</pre></article><article class=\"template\"><h3>03 — Pause sans réponse</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Objet : Votre demande Solaya — mise en pause\n\nBonjour [Prénom],\n\nSans retour de votre part, je mets le suivi de votre demande en pause. Vous pourrez reprendre contact quand le moment sera plus adapté. Merci pour votre intérêt et bonne continuation dans votre projet.\n\nKevin — Solaya Collection</pre></article><article class=\"template\"><h3>04 — Confirmation de rendez-vous</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Objet : Notre échange du [date] à [heure, fuseau]\n\nBonjour [Prénom],\n\nComme convenu, nous échangerons le [date] à [heure] par [téléphone / lien de visioconférence vérifié]. Prévoyons 20 minutes.\n\nNous aborderons votre logement, votre objectif et les prochaines étapes possibles. Si vous devez décaler, répondez à ce message.\n\nKevin — Solaya Collection</pre></article><article class=\"template\"><h3>05 — Après qualification</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Objet : Votre projet — récapitulatif et éléments à préparer\n\nBonjour [Prénom],\n\nVoici ce que nous avons retenu :\n• Votre priorité : [objectif].\n• Le logement et sa disponibilité : [faits].\n• Les points à vérifier : [liste].\n• Les informations utiles à l’étude : [données strictement nécessaires].\n\nNotre prochaine étape : [action] pour [date convenue]. Merci de me corriger si un point ne reflète pas notre échange.\n\nKevin — Solaya Collection</pre></article><article class=\"template\"><h3>06 — Pièces manquantes</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Objet : Un point pour terminer votre étude\n\nBonjour [Prénom],\n\nIl nous manque [élément précis] pour avancer sur [partie de l’étude]. Pouvez-vous nous le transmettre ou nous indiquer s’il n’est pas disponible ? Dans ce cas, nous distinguerons explicitement les hypothèses des données constatées.\n\nKevin — Solaya Collection</pre></article><article class=\"template\"><h3>07 — Présentation de la proposition</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Objet : Votre proposition Solaya — [logement]\n\nBonjour [Prénom],\n\nVous trouverez en pièce jointe la proposition que nous avons préparée pour [logement]. Elle détaille les prestations, les frais, les responsabilités et les étapes de mise en service.\n\nLes scénarios de revenus dépendent des hypothèses précisées dans l’étude et ne constituent pas une garantie. Je vous propose un échange pour parcourir les points importants ensemble. Quels créneaux vous conviendraient ?\n\nKevin — Solaya Collection\n\n[Avant envoi : joindre la version validée, vérifier les montants et supprimer cette instruction.]</pre></article><article class=\"template\"><h3>08 — Après proposition</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Objet : Une question sur votre proposition Solaya ?\n\nBonjour [Prénom],\n\nAvez-vous pu parcourir la proposition ? Quel point mérite d’être précisé pour vous aider à décider : les prestations, les frais, le calendrier ou la gestion au quotidien ?\n\nSi le projet est reporté, nous pouvons convenir ensemble d’une date de reprise.\n\nKevin — Solaya Collection</pre></article><article class=\"template\"><h3>09 — Proposition en pause</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Objet : Suite de votre projet Solaya\n\nBonjour [Prénom],\n\nJe n’ai pas eu de retour sur la proposition. Je mets le dossier en pause pour le moment. Si vous souhaitez reprendre l’étude, nous vérifierons ensemble que ses conditions et notre disponibilité sont toujours adaptées.\n\nMerci pour nos échanges.\nKevin — Solaya Collection</pre></article><article class=\"template\"><h3>10 — Après signature</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Objet : Préparons la mise en service de votre logement\n\nBonjour [Prénom],\n\nNous avons reçu votre contrat signé. Voici les prochaines étapes à organiser :\n1. Vérifier les documents et autorisations applicables au bien.\n2. Confirmer ménage, linge et interventions.\n3. Tester les accès et la solution de secours.\n4. Finaliser les photos, le descriptif et le calendrier.\n5. Vérifier le circuit de paiement et le suivi propriétaire.\n\nVotre interlocuteur est [nom]. Nous vous proposons un point le [date à convenir]. La date de mise en service sera confirmée après ces contrôles.\n\nKevin — Solaya Collection</pre></article><article class=\"template\"><h3>11 — Projet non retenu</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Objet : Retour sur votre projet à [Ville]\n\nBonjour [Prénom],\n\nMerci pour les informations partagées. À ce stade, nous ne pouvons pas vous proposer un accompagnement adapté, car [raison factuelle : couverture terrain, disponibilité, contrainte non résolue].\n\nNous préférons vous le préciser avant tout engagement. [Si pertinent et accepté : proposition d’orientation, sans transmettre vos coordonnées sans votre accord.]\n\nKevin — Solaya Collection</pre></article><article class=\"template\"><h3>12 — Conseil réservé aux inscrits volontaires</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Objet : Le chiffre à regarder avant de déléguer\n\nBonjour [Prénom],\n\nPour comparer deux modes de location, les recettes seules ne suffisent pas. Listez aussi les frais de plateformes, la gestion, les consommables, l’entretien et les dépenses de mise en service. Distinguez ensuite ce qui revient chaque mois de ce qui ne se paie qu’au départ.\n\nNotre guide vous aide à préparer cette comparaison : [lien du guide].\n\nKevin — Solaya Collection\nVous recevez ce conseil car vous avez demandé nos actualités. Pour ne plus les recevoir, répondez « arrêt ». Nous traiterons votre demande et retirerons votre inscription.</pre></article></section><section id=\"s7\"><h2>08 · Sept publications prêtes à personnaliser</h2><article class=\"template\"><h3>1 · La charge invisible</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Une location ne se gère pas seulement entre deux réservations. Il y a les messages, les horaires d’arrivée, le ménage à coordonner et les imprévus.\n\nAvec Solaya Collection, nous commençons par regarder ce qui vous prend réellement du temps, puis les services adaptés à votre logement.\n\nPropriétaire à Toulouse ou dans les environs ? Présentez-nous votre projet : [lien].\n\nVisuel : une liste de tâches sobre, sur fond sable ; pas de faux témoignage.</pre></article><article class=\"template\"><h3>2 · Recettes ou revenu net ?</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Un chiffre d’affaires locatif n’est pas un revenu net. Avant de choisir votre mode de location, mettez les frais et les investissements à côté des recettes.\n\nDans nos études, les hypothèses sont explicites et les scénarios restent des scénarios. Aucun revenu garanti.\n\nPréparez votre réflexion avec notre guide propriétaire : [lien].\n\nVisuel : deux colonnes « recettes » / « dépenses à intégrer », sans montants inventés.</pre></article><article class=\"template\"><h3>3 · Vous louez déjà</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Votre logement est déjà en location, mais vous aimeriez moins gérer au quotidien ?\n\nCommençons par vos contraintes : ce que vous voulez déléguer, vos périodes personnelles et ce que vous souhaitez garder sous contrôle.\n\nSolaya Collection prépare avec vous une organisation adaptée. Premier échange sans engagement : [lien segment déjà].</pre></article><article class=\"template\"><h3>4 · Avant de se lancer</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Avant de publier une annonce : vérifier les règles du logement, prévoir les dépenses initiales, organiser le ménage et tester les accès.\n\nCes points font partie du projet. Nous les regardons avec vous avant une mise en service.\n\nVotre logement est à Toulouse ou dans les environs ? Parlons-en : [lien segment nouveau].</pre></article><article class=\"template\"><h3>5 · La singularité du lieu</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Un lieu accueillant raconte quelque chose : la lumière, les matières, les détails utiles et la manière dont le voyageur s’y sent attendu.\n\nC’est l’esprit de Solaya Collection. Une attention à l’expérience, associée à une organisation concrète du séjour.\n\nVous souhaitez faire évoluer votre logement ? [lien].\n\nVisuel : photo réelle autorisée, ou illustration explicitement présentée comme une inspiration.</pre></article><article class=\"template\"><h3>6 · Les bonnes questions</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Avant de choisir un accompagnement, demandez :\n— Qui intervient sur place ?\n— Quels frais s’ajoutent ?\n— Comment sont gérés les imprévus ?\n— Quelle visibilité vais-je conserver ?\n\nNotre guide rassemble 7 questions utiles : [lien guide].</pre></article><article class=\"template\"><h3>7 · Rencontre locale</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Nous préparons Solaya Collection avec une conviction simple : l’expérience du voyageur dépend aussi de la qualité de l’organisation locale.\n\nProfessionnels du ménage, du linge, de la photographie ou de l’entretien autour de Toulouse : nous souhaitons échanger sur vos périmètres et votre façon de travailler.\n\nContact : kevin.dolie@solayia.fr.\n\nNe pas annoncer de partenariat avant son accord.</pre></article><p>Cadence proposée : deux publications par semaine, adaptées au canal. Ajouter uniquement des photos dont les droits sont acquis. Transformer les premières missions en cas clients seulement avec autorisation, chiffres vérifiables et contexte ; ne pas fabriquer d’avis ou de résultats.</p></section><section id=\"s8\"><h2>09 · Entretien de qualification de 20 minutes</h2><div class=\"table-wrap\"><table><thead><tr><th>Minute</th><th>Question / action</th><th>À consigner</th></tr></thead><tbody><tr><td>0–2</td><td>« Qu’aimeriez-vous avoir clarifié à la fin de cet échange ? »</td><td>Priorité exprimée dans les mots du propriétaire.</td></tr><tr><td>2–5</td><td>« Où se trouve le bien ? Qui décide ? Quelles périodes souhaitez-vous conserver ? »</td><td>Commune, décideurs, calendrier, contraintes.</td></tr><tr><td>5–9</td><td>« Comment cela fonctionne aujourd’hui ? Qu’est-ce qui vous prend du temps ? »</td><td>Situation, annonces, prestataires, contrat existant, irritants.</td></tr><tr><td>9–12</td><td>« Quelles recettes et charges connaissez-vous ? Quels équipements ou travaux sont prévus ? »</td><td>Données disponibles / inconnues, investissement acceptable.</td></tr><tr><td>12–15</td><td>« Quelles vérifications avez-vous déjà faites pour cette adresse ? »</td><td>Statut, règlement, démarches à confirmer avec interlocuteur compétent.</td></tr><tr><td>15–18</td><td>Expliquer ce que l’étude pourra établir et ce qui reste à vérifier.</td><td>Adéquation, périmètre possible, absence de garantie.</td></tr><tr><td>18–20</td><td>« Voici la prochaine étape que je vous propose. Est-ce adapté ? »</td><td>Action, responsable, date convenue, mode de contact.</td></tr></tbody></table></div><article class=\"template\"><h3>Compte rendu à coller dans la fiche</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Date / interlocuteurs :\nLogement / décideurs :\nObjectif principal :\nSituation actuelle et difficultés :\nPériodes disponibles / usage personnel :\nDonnées constatées reçues :\nHypothèses encore nécessaires :\nContraintes / autorisations à vérifier :\nCouverture ménage et capacité :\nBudget d’équipement évoqué :\nCritères de décision / autres options :\nConclusion : qualifié / à approfondir / en pause / non adapté\nProchaine action / responsable / date :\nAccord sur la suite et canal :</pre></article><div class=\"table-wrap\"><table><thead><tr><th>Objection</th><th>Réponse à adapter</th></tr></thead><tbody><tr><td>« La commission est élevée. »</td><td>Comparons le périmètre complet et ce qui restera à votre charge. Je peux vous expliquer chaque ligne et son effet sur le scénario net.</td></tr><tr><td>« Pouvez-vous garantir un revenu ? »</td><td>Non. Nous pouvons documenter plusieurs scénarios et leurs hypothèses, puis suivre les résultats constatés.</td></tr><tr><td>« Je veux garder mon logement certains week-ends. »</td><td>Précisons ces périodes avant les scénarios et la proposition : elles modifient la disponibilité et l’organisation.</td></tr><tr><td>« Je veux garder la main. »</td><td>Définissons les accès, le calendrier, les plafonds de dépenses et le rythme de reporting que vous souhaitez.</td></tr><tr><td>« Je suis déjà engagé avec une conciergerie. »</td><td>Vérifions d’abord les conditions et délais de votre contrat actuel. Nous n’organiserons pas un transfert sans les clarifier.</td></tr><tr><td>« Je veux réfléchir. »</td><td>Quel point vous manque pour décider ? Si le projet reste pertinent, convenons d’une date de reprise ; sinon nous mettons en pause.</td></tr></tbody></table></div></section><section id=\"s9\"><h2>10 · Trame d’étude du logement</h2><p>Ne remplir aucune donnée de marché par intuition. Pour chaque hypothèse : source, date, périmètre, limites. Les prix affichés d’annonces concurrentes ne sont pas des revenus encaissés.</p><article class=\"template\"><h3>Dossier d’étude — à dupliquer par logement</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">ÉTUDE SOLAYA — [référence / date / version]\n\n1. Le projet\nAdresse / caractéristiques / capacité réelle :\nObjectifs et périodes personnelles :\nDécideurs / contraintes connues :\n\n2. Faisabilité\nDémarches applicables à confirmer :\nRèglement et restrictions connus :\nCouverture ménage / linge / dépannage :\nÉquipements, sécurité et état :\nPoints bloquants / responsable / échéance :\n\n3. Données\nHistorique fourni (période, recettes, nuits, frais) :\nSources de comparaison (URL, date, comparable ou non) :\nDonnées manquantes et effet sur la confiance :\n\n4. Trois scénarios : prudent / central / haut\nNuits disponibles après usage personnel :\nNuits vendues envisagées :\nPrix moyen par nuit hors ménage :\nRecettes = nuits vendues × prix moyen :\nFrais plateformes :\nHonoraires de gestion :\nMénage restant à charge, s’il y en a :\nConsommables / entretien / charges / assurance :\nContribution avant financement et fiscalité personnelle :\nInvestissements ponctuels (séparés) :\n\n5. Décision\nÉcart avec l’option actuelle, à périmètre comparable :\nSensibilité à une baisse de nuits / de prix :\nPrestations recommandées et exclusions :\nConditions préalables / décision / prochaine étape :</pre></article><h3>Formules à utiliser</h3><p>Recettes hébergement = nuits vendues × prix moyen. Honoraires = base contractuelle × taux contractuel. Ne déduire qu’une fois les frais de plateformes et de ménage. Identifier qui facture et qui encaisse chaque flux. Présenter séparément le financement, les impôts et les travaux ; ne pas appeler « bénéfice net » une contribution qui les exclut.</p><p>Le scénario haut est une sensibilité, pas une cible garantie. Distinguer la saisonnalité : une moyenne mensuelle annuelle ne signifie pas une recette identique chaque mois.</p></section><section id=\"s10\"><h2>11 · Proposition commerciale et signature</h2><article class=\"template\"><h3>Proposition — texte maître à personnaliser</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">SOLAYA COLLECTION\nProposition d’accompagnement — [propriétaire / bien]\nVersion [date] — Validité [durée validée]\n\nVotre objectif\nVous souhaitez [objectif fidèle] pour [logement], avec [contraintes et périodes personnelles].\n\nNotre proposition\nNous proposons [périmètre exact]. La mise en service dépend des vérifications et préparatifs listés ci-dessous.\n\nPrestations incluses\n[Annonces / coordination voyageurs / ménage / linge / suivi / page directe : sélectionner seulement ce qui est contractualisé et réalisable.]\nFréquence, disponibilité et limites : [à préciser].\n\nPrestations exclues ou facturées séparément\n[Travaux, matériel, installation, photographie, déplacements, urgences, frais plateformes, linge… selon offre validée.]\n\nConditions économiques\nFrais de démarrage : [montant HT, TVA applicable, TTC].\nHonoraires récurrents : [taux, base de calcul précise, TVA, exemples cohérents].\nMénage : [qui paie, qui facture, qui encaisse, cas d’annulation].\nAutres frais : [liste et mode de validation préalable].\nPaiement et reversement : [circuit et échéances].\n\nOrganisation\nInterlocuteur : [nom].\nVisibilité propriétaire : [reporting, accès, calendrier].\nDépenses autorisées : [plafond et procédure].\nUsage personnel : [règle].\nImprévus : [contacts, horaires et procédure réellement disponibles].\n\nPréparation et calendrier\n[Action / responsable / date].\nDate de mise en service à confirmer après contrôles.\n\nScénarios\nL’étude jointe présente des hypothèses, pas une garantie de revenus.\n\nCadre contractuel\nIdentité de l’entité, responsabilités, assurances, durée, fin de contrat, restitution des accès, droits sur les contenus et règles de facturation : se référer au contrat validé annexé.\n\nProchaine étape\nPrésentation de la proposition, réponses aux questions, puis signature du contrat si les conditions conviennent aux parties.\n\n[DOCUMENT DE TRAVAIL : compléter tous les champs et faire valider les conditions avant envoi.]</pre></article><h3>Contrôle avant envoi</h3><ul><li>Aucun champ entre crochets ; bon destinataire et bon logement.</li><li>Prix et base de commission cohérents entre l’étude, la proposition et le contrat.</li><li>Exclusions explicites, capacité terrain confirmée, calendrier réaliste.</li><li>Pièces jointes correctes et version archivée ; date d’envoi notée dans le CRM.</li><li>Le contrat, les assurances et le circuit financier sont validés par Adrien avec le professionnel compétent selon le périmètre retenu.</li></ul><p>Ce document prépare la vente ; il ne remplace pas le contrat juridiquement adapté à votre activité. Aucun service de signature électronique n’est raccordé. Passer en « signé » seulement après réception du contrat exécuté par les parties requises.</p></section><section id=\"s11\"><h2>12 · Intégration et première mise en service</h2><div class=\"table-wrap\"><table><thead><tr><th>Bloc</th><th>Livrable attendu</th><th>Contrôle / pilote</th></tr></thead><tbody><tr><td>Contrat et dossier</td><td>Contrat signé, identité des parties, références des autorisations, contacts et coordonnées de facturation dans un espace adapté.</td><td>Adrien : liens sécurisés dans les notes, pas de mots de passe en clair.</td></tr><tr><td>Ménage et linge</td><td>Prestataire, périmètre, prix, créneaux, check-list, preuve de contrôle, suppléant.</td><td>Adrien : intervention test ou visite documentée.</td></tr><tr><td>Accès</td><td>Instructions, remise des clés ou serrure, secours, procédure perte/panne.</td><td>Adrien : arrivée test, accès au logement réellement vérifié.</td></tr><tr><td>Logement</td><td>Inventaire, consommables, équipements, photos, points d’entretien.</td><td>Les deux : écarts consignés et corrigés.</td></tr><tr><td>Contenus</td><td>Annonce exacte, photos autorisées, capacité, règles, guide local, informations d’arrivée.</td><td>Kevin : relecture propriétaire ; pas de fausse disponibilité.</td></tr><tr><td>Réservation et paiement</td><td>Calendrier, tarifs, restrictions, parcours paiement/remboursement et reversement.</td><td>Kevin + Adrien : tests avec outil retenu, sans encaissement fictif annoncé.</td></tr><tr><td>Communication</td><td>Messages voyageurs, interlocuteur, créneaux, urgences, compte rendu propriétaire.</td><td>Les deux : responsabilités confirmées et coordonnées vérifiées.</td></tr><tr><td>Go de mise en service</td><td>Tous les points bloquants clos et accord interne consigné.</td><td>Adrien pour terrain / Kevin pour parcours digital.</td></tr></tbody></table></div><article class=\"template\"><h3>Point après les premiers séjours</h3><button class=\"copy\">Copier</button><pre contenteditable=\"true\" spellcheck=\"true\">Référence logement / période :\nSéjours réalisés / incidents constatés :\nQualité ménage / retours voyageurs :\nTemps passé et coûts réels :\nRecettes et frais rapprochés :\nÉcart avec les hypothèses et causes possibles :\nActions correctives / responsables / dates :\nRetour du propriétaire :\nDécision : poursuivre / ajuster / suspendre :</pre></article><p>Prévoir un point après les premiers séjours puis un bilan mensuel. Solliciter un témoignage seulement après une expérience réelle et obtenir l’accord sur son contenu et sa diffusion.</p></section><section id=\"s12\"><h2>13 · Mesure, coûts et décisions</h2><div class=\"table-wrap\"><table><thead><tr><th>Indicateur</th><th>Calcul</th><th>Décision utile</th></tr></thead><tbody><tr><td>Demandes attribuées</td><td>Nombre de demandes par source/campagne, période donnée.</td><td>Quels canaux amènent des projets.</td></tr><tr><td>Qualification</td><td>Biens qualifiés / demandes de la même cohorte.</td><td>Qualité du ciblage, pas seulement volume.</td></tr><tr><td>Signature</td><td>Contrats signés / demandes de la même cohorte.</td><td>Performance commerciale ; attendre un délai de décision suffisant.</td></tr><tr><td>Activation</td><td>Biens actifs / contrats signés de la même cohorte.</td><td>Qualité du passage entre vente et exploitation.</td></tr><tr><td>Coût par demande</td><td>Dépenses du canal / demandes attribuées.</td><td>Coût de l’entrée ; aucune preuve de rentabilité seule.</td></tr><tr><td>Coût d’acquisition</td><td>Dépenses + coût du temps commercial / nouveaux clients signés.</td><td>Comparer à une contribution réaliste et au délai de récupération.</td></tr><tr><td>Délai de traitement</td><td>Première action réelle − demande reçue.</td><td>Détecter la saturation ; horodatage des actions à consigner.</td></tr><tr><td>Motifs de perte</td><td>Zone, prix, délai, faisabilité, sans réponse, autre documenté.</td><td>Modifier offre, couverture ou discours.</td></tr></tbody></table></div><p>La vue CRM montre les états actuels, pas des taux historiques par cohorte. Exporter les demandes et rapprocher les dates/notes pour le bilan mensuel. « Signé » n’est pas « encaissé » ; un logement actif n’est pas nécessairement rentable.</p><h3>Exemple interne, entièrement hypothétique</h3><p>Si un bien génère 1 800 € de recettes mensuelles et que l’honoraire est 20 % TTC avec TVA à 20 %, le revenu de gestion est 300 € HT. Avec 25 € de coûts directs et 3,5 heures valorisées 25 €/h, la contribution illustrative est 187,50 € avant frais fixes et autres charges. Ce n’est ni une estimation de marché ni une situation fiscale confirmée.</p><p>Un coût d’acquisition de 300 € serait récupéré en environ 1,6 mois de cette contribution, uniquement si le bien fonctionne déjà à ce niveau. Le démarrage, les mois faibles, les pertes de clients et les dépenses d’installation peuvent allonger ce délai. Fixer un plafond de CAC après observations et validation du modèle par Adrien.</p></section><section id=\"s13\"><h2>14 · Automatisations : périmètre réel et raccordements</h2><div class=\"table-wrap\"><table><thead><tr><th>Déclencheur</th><th>Déjà en place</th><th>Suite préparée</th></tr></thead><tbody><tr><td>Formulaire envoyé</td><td>Validation, référence unique, stockage, source/campagne, accord marketing horodaté, prochaine journée ouvrée.</td><td>Raccorder une alerte interne avec reprise sur erreur.</td></tr><tr><td>Demande répétée</td><td>Même clé de requête : même référence ; trois demandes par e-mail et par heure au maximum.</td><td>Protection anti-abus publique à renforcer selon trafic ; seuil e-mail pas une défense exhaustive.</td></tr><tr><td>Édition CRM</td><td>Droits admin côté serveur, version pour éviter un écrasement concurrent, historique.</td><td>Notification au responsable après ajout de son accès et de son canal.</td></tr><tr><td>Relance à préparer</td><td>Brouillon consultable/copiant ; blocage copie si arrêt de contact.</td><td>Envoi seulement après connexion messagerie et validation des destinataires, consentements et règles.</td></tr><tr><td>Contrat signé</td><td>Contrôle de la case « contrat reçu ».</td><td>Raccorder un service de signature ; vérifier webhook signé, unicité de l’événement et archive.</td></tr><tr><td>Passage actif</td><td>Contrôles de qualification, contrat, démarches, ménage, accès, paiement, photos.</td><td>Créer les tâches d’exploitation dans l’outil retenu.</td></tr><tr><td>Conservation</td><td>Effacement manuel du dossier et historique.</td><td>Revue mensuelle des dossiers sans échange depuis 12 mois ; pas de purge automatique annoncée.</td></tr></tbody></table></div><h3>Contrat d’automatisation à transmettre lors du raccordement</h3><p>Événement <code>lead.created</code> : identifiant de demande, date, responsable et lien vers le CRM. Éviter les données complètes dans une notification. Conserver un identifiant d’événement unique pour empêcher les doublons. Sur échec, journaliser l’erreur et la rendre visible ; aucune notification « envoyée » sans confirmation du fournisseur.</p><p>Événement <code>followup.due</code> : revérifier au moment de l’envoi le statut, l’arrêt de contact, la réponse éventuelle, le consentement pertinent et la limite de tentatives. Une échéance seule ne doit jamais déclencher une nouvelle campagne commerciale.</p><p>La base actuelle reste la source du suivi. Ne pas ajouter Notion, un tableur et une autre base comme trois référentiels concurrents. Une intégration future doit choisir un sens de synchronisation et un identifiant stable.</p></section><section id=\"s14\"><h2>15 · Dernières décisions avant diffusion</h2><p>Cochez les éléments terminés. Les cases sont mémorisées dans ce navigateur, sans modifier le CRM. Les modèles restent modifiables à l’écran ; copiez vos versions avant de fermer le document.</p><div class=\"checklist\"><label><input type=\"checkbox\" data-task=\"0\"> Adrien : entité juridique, adresse, assurances et périmètre contractuel confirmés.</label><label><input type=\"checkbox\" data-task=\"1\"> Adrien : 490 € / commission / HT-TTC / base de calcul / frais externes tranchés.</label><label><input type=\"checkbox\" data-task=\"2\"> Adrien : couverture terrain, ménage, linge, dépannage et capacité de nouveaux biens confirmés.</label><label><input type=\"checkbox\" data-task=\"3\"> Kevin : domaine et boîte de contact validés ; test de réception et réponse effectué.</label><label><input type=\"checkbox\" data-task=\"4\"> Kevin : mentions légales et information données finalisées avec l’identité réelle.</label><label><input type=\"checkbox\" data-task=\"5\"> Kevin : parcours formulaire → référence → fiche CRM vérifié avec un dossier de test supprimé ensuite.</label><label><input type=\"checkbox\" data-task=\"6\"> Kevin : accès administrateur testé ; accès d’Adrien à organiser séparément si nécessaire.</label><label><input type=\"checkbox\" data-task=\"7\"> Les deux : contrat, proposition et étude cohérents ; procédure de signature choisie.</label><label><input type=\"checkbox\" data-task=\"8\"> Kevin : liens de campagne avec bonne racine et attribution vérifiés.</label><label><input type=\"checkbox\" data-task=\"9\"> Les deux : créneaux de qualification et traitement quotidien réservés.</label><label><input type=\"checkbox\" data-task=\"10\"> Kevin : ouverture du site au public décidée et effectuée avant de diffuser les liens.</label><label><input type=\"checkbox\" data-task=\"11\"> Les deux : plafond de dépenses décidé avant toute activation publicitaire.</label><label><input type=\"checkbox\" data-task=\"12\"> Kevin : absence de faux biens, de faux avis et de résultats non prouvés vérifiée.</label><label><input type=\"checkbox\" data-task=\"13\"> Les deux : premier bilan commercial et revue de conservation des données planifiés.</label></div><h3>Références et provenance</h3><p>Positionnement, tâches et hypothèses tarifaires : <a href=\"https://docs.google.com/document/d/1EtMFYLG0sAZktViXdXpRlgv21sI5ZadePRauXs8EeCU/edit\">document de travail Solaya</a> et <a href=\"https://docs.google.com/document/d/1CP5FSfM9dqCJwLCyU2jeCH1ICNo47BSjL76k35mwco0/edit\">réunion du 11 septembre</a>. Le présent kit transforme ces orientations en propositions opérationnelles ; les cadences, scores et budgets de test sont proposés, non déjà approuvés.</p><p>Pour les e-mails commerciaux aux particuliers, le consentement préalable est en principe requis ; pour la prospection professionnelle pertinente, les règles diffèrent et l’opposition doit rester simple. Les cases de consentement ne sont pas précochées. Voir la <a href=\"https://www.cnil.fr/fr/la-prospection-commerciale-par-courrier-electronique-sms-mms-et-automate-dappel\">fiche CNIL sur la prospection électronique</a>. L’information de collecte doit être adaptée au responsable, aux finalités et au fonctionnement réels : <a href=\"https://www.cnil.fr/fr/exemples-de-formulaire-de-collecte-de-donnees-caractere-personnel\">exemples CNIL</a>. Références consultées le 14 septembre 2026.</p></section></main></div><footer>Solaya Collection · Préparation interne. Les contenus de campagne et messages nécessitent une relecture avant diffusion.</footer><script>document.querySelectorAll(\".copy\").forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.parentElement.querySelector(\"pre\").innerText);b.textContent=\"Copié\";setTimeout(()=>b.textContent=\"Copier\",1500)}catch{b.textContent=\"Sélectionnez le texte\"}});document.querySelectorAll(\"[data-task]\").forEach(c=>{try{c.checked=localStorage.getItem(\"solaya-tunnel-v2-\"+c.dataset.task)===\"1\"}catch{}c.onchange=()=>{try{localStorage.setItem(\"solaya-tunnel-v2-\"+c.dataset.task,c.checked?\"1\":\"0\")}catch{}}});</script></html>";
